    },
    "data": {
      "weather": {
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/bolt_fill.svg",
      "description": "闪电实心图标，适合用于用电量、电费余量或充电状态识别。"
    }
  ]
}

